CREATE TABLE command_lock (id INT PRIMARY KEY);
INSERT INTO command_lock VALUES (1);
CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, handle VARCHAR(32) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE auth_attempts (identity_key CHAR(64) PRIMARY KEY, attempts INT NOT NULL, reset_at TIMESTAMP(6) NOT NULL);
CREATE TABLE instruments (symbol VARCHAR(16) PRIMARY KEY, base_asset VARCHAR(12) NOT NULL, quote_asset VARCHAR(12) NOT NULL, reference_price DECIMAL(28,8) NOT NULL, price_tick DECIMAL(28,8) NOT NULL, quantity_step DECIMAL(28,8) NOT NULL, min_notional DECIMAL(28,8) NOT NULL, rule_version INT NOT NULL, state VARCHAR(16) NOT NULL);
INSERT INTO instruments VALUES ('BTCUSDT','BTC','USDT',65000,0.01,0.00001,5,1,'TRADING'),('ETHUSDT','ETH','USDT',3200,0.01,0.0001,5,1,'TRADING'),('SOLUSDT','SOL','USDT',150,0.01,0.001,5,1,'TRADING');
CREATE TABLE balances (owner_id VARCHAR(36) NOT NULL, wallet VARCHAR(16) NOT NULL, asset VARCHAR(12) NOT NULL, available DECIMAL(28,8) NOT NULL DEFAULT 0, held DECIMAL(28,8) NOT NULL DEFAULT 0, PRIMARY KEY(owner_id,wallet,asset));
CREATE TABLE journal (id BIGINT AUTO_INCREMENT PRIMARY KEY, reference_id VARCHAR(64) NOT NULL UNIQUE, kind VARCHAR(32) NOT NULL, created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE postings (id BIGINT AUTO_INCREMENT PRIMARY KEY, journal_id BIGINT NOT NULL, owner_id VARCHAR(36) NOT NULL, wallet VARCHAR(16) NOT NULL, asset VARCHAR(12) NOT NULL, bucket VARCHAR(12) NOT NULL, amount DECIMAL(28,8) NOT NULL, FOREIGN KEY(journal_id) REFERENCES journal(id));
CREATE INDEX posting_owner ON postings(owner_id,id);
CREATE TABLE orders (id VARCHAR(36) PRIMARY KEY, sequence_id BIGINT AUTO_INCREMENT UNIQUE, owner_id VARCHAR(36) NOT NULL, symbol VARCHAR(16) NOT NULL, side VARCHAR(4) NOT NULL, order_type VARCHAR(8) NOT NULL, time_in_force VARCHAR(4) NOT NULL, price DECIMAL(28,8) NOT NULL, quantity DECIMAL(28,8) NOT NULL, remaining DECIMAL(28,8) NOT NULL, hold_amount DECIMAL(28,8) NOT NULL, state VARCHAR(20) NOT NULL, rule_version INT NOT NULL, created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE INDEX matching ON orders(symbol,side,state,price,sequence_id);
CREATE TABLE fills (id BIGINT AUTO_INCREMENT PRIMARY KEY, symbol VARCHAR(16) NOT NULL, maker_order VARCHAR(36) NOT NULL, taker_order VARCHAR(36) NOT NULL, buyer VARCHAR(36) NOT NULL, seller VARCHAR(36) NOT NULL, price DECIMAL(28,8) NOT NULL, quantity DECIMAL(28,8) NOT NULL, quote_amount DECIMAL(28,8) NOT NULL, buyer_fee DECIMAL(28,8) NOT NULL, seller_fee DECIMAL(28,8) NOT NULL, created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE commands (owner_id VARCHAR(36) NOT NULL, command_id VARCHAR(64) NOT NULL, fingerprint CHAR(64) NOT NULL, result_id VARCHAR(64) NOT NULL, PRIMARY KEY(owner_id,command_id));
CREATE TABLE outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY, event_type VARCHAR(32) NOT NULL, aggregate_id VARCHAR(64) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE subscriptions (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL, asset VARCHAR(12) NOT NULL, product VARCHAR(16) NOT NULL, principal DECIMAL(28,8) NOT NULL, state VARCHAR(16) NOT NULL, created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6));
